import unittest
from rosterkit.notices import absence_notice
from rosterkit.models import Student, Mark
from rosterkit.errors import ProjectError
from datetime import date

PUPIL = Student("s1", "Lovelace", "Ada", "A")


def mark(ident, month, status):
    return Mark(ident, date(2024, month, 1), status)


class NoticeTests(unittest.TestCase):
    def test_lists_absent_dates_in_order(self):
        marks = [
            mark("s1", 3, "absent"),
            mark("s1", 2, "present"),
            mark("s1", 1, "absent")
        ]
        self.assertEqual(
            absence_notice(PUPIL, marks),
            "Ada Lovelace missed 2 day(s): "
            "2024-01-01, 2024-03-01."
        )

    def test_other_student_rejected(self):
        marks = [
            mark("s1", 1, "absent"),
            mark("s2", 2, "absent")
        ]
        with self.assertRaises(ProjectError):
            absence_notice(PUPIL, marks)

    def test_no_absences_rejected(self):
        with self.assertRaises(ProjectError):
            absence_notice(PUPIL, [mark("s1", 1, "late")])
